import { defineRailway, github, project, service } from "railway/iac";
// Generated by `railway config migrate --service adte-detection-triage-engine --variables unmanaged`
// (CLI 5.68.0, dry run, 2026-10-16) from railway.json, then hand-annotated.
//
// This repository manages only its own resources in the environment. Other
// repositories export their own partial name.
// See https://docs.railway.com/infrastructure-as-code#multi-repo-projects
export const partial = "adte-detection-triage-engine";
export default defineRailway(() => {
  const adteDetectionTriageEngine = service("adte-detection-triage-engine", {
    // The builder was set only by railway.json. The migrator drops it, but
    // `build` accepts it, and IaC nulls any field it owns that the file leaves
    // out, so it must be declared here. The dashboard builder default is
    // RAILPACK; this service builds from the two-stage Dockerfile (Node
    // frontend bundle, then the Python runtime). The gunicorn start command
    // lives in the Dockerfile's CMD, with the single-worker reasoning.
    //
    // No restart policy on purpose: railway.json asked for ON_FAILURE with 10
    // retries, which is exactly Railway's default ("The default is On Failure
    // with a maximum of 10 restarts", docs.railway.com/deployments/restart-policy).
    // The API stores a default as null, so declaring either field leaves a plan
    // diff that never clears (seen 2026-10-16: retries stayed null -> 10 after
    // an apply).
    build: { builder: "DOCKERFILE", dockerfilePath: "Dockerfile" },
    //
    // checkSuites true = Railway waits for this repo's GitHub CI
    // (.github/workflows/ci.yml) to pass before it deploys a commit on main.
    source: github("dlpz-SEC/adte-detection-triage-engine", { branch: "main", checkSuites: true }),
    // The dependency-free /health route in adte/server.py (no threat-intel,
    // LLM or SIEM call), so a healthcheck never spends an API quota.
    healthcheck: "/health",
    healthcheckTimeout: 30,
    replicas: { "sfo": 1 },
  });

  return project("Projects", {
    // Variables stay owned by the dashboard (David's decision, 2026-10-15), so
    // no variable names or secrets live in this repo.
    variables: { managed: false },
    resources: [adteDetectionTriageEngine],
  });
});
